/**
 * Taboola Adapter
 * 
 * Adapts event data into Taboola Pixel format.
 * 
 * Documentation:
 * - https://help.taboola.com/hc/en-us/articles/360009027493-Tracking-Dynamic-Conversion-Values-
 * 
 * @since 1.51.0
 */

(function (wpm, $, undefined) {

	class TaboolaAdapter {
		
		/**
		 * Adapt event data to Taboola Pixel format
		 * 
		 * @param {object} eventData - Event-specific data (product, order, etc.)
		 * @param {string} eventName - Standardized event name
		 * @param {object} context - Event context (user, page, etc.)
		 * @returns {object|null} Adapted data for Taboola or null if pixel not loaded
		 */
		adapt(eventData, eventName, context) {
			
			// Check if Taboola pixel is loaded
			if (!wpmDataLayer?.pixels?.taboola?.loaded) {
				return null;
			}
			
			const eventMap = {
				'search': () => this.adaptSearch(eventData),
				'add_to_cart': () => this.adaptAddToCart(eventData),
				'add_to_wishlist': () => this.adaptAddToWishlist(eventData),
				'begin_checkout': () => this.adaptStartCheckout(eventData),
				'view_item': () => this.adaptViewContent(eventData),
				'purchase': () => this.adaptPurchase(eventData),
			};
			
			if (!eventMap[eventName]) {
				return null;
			}
			
			return eventMap[eventName]();
		}
		
		/**
		 * Adapt search event
		 */
		adaptSearch(eventData) {
			return {
				id: wpmDataLayer.pixels.taboola.account_id,
				notify: 'event',
				name: wpmDataLayer.pixels.taboola.event_names.search,
			};
		}
		
		/**
		 * Adapt add_to_cart event
		 * No product value transmitted, as Taboola only supports the "revenue" field.
		 */
		adaptAddToCart(eventData) {
			if (!eventData?.product) return null;
			
			const product = eventData.product;
			
			return {
				id: wpmDataLayer.pixels.taboola.account_id,
				notify: 'event',
				name: wpmDataLayer.pixels.taboola.event_names.add_to_cart,
				quantity: product.quantity,
				currency: product.currency,
				revenue: product.quantity * product.price,
			};
		}
		
		/**
		 * Adapt add_to_wishlist event
		 * No product value transmitted, as Taboola only supports the "revenue" field.
		 */
		adaptAddToWishlist(eventData) {
			if (!eventData?.product) return null;
			
			const product = eventData.product;
			
			return {
				id: wpmDataLayer.pixels.taboola.account_id,
				notify: 'event',
				name: wpmDataLayer.pixels.taboola.event_names.add_to_wishlist,
				quantity: product.quantity,
				currency: product.currency,
				revenue: product.quantity * product.price,
			};
		}
		
		/**
		 * Adapt start_checkout event
		 * No product value transmitted, as Taboola only supports the "revenue" field.
		 */
		adaptStartCheckout(eventData) {
			return {
				id: wpmDataLayer.pixels.taboola.account_id,
				notify: 'event',
				name: wpmDataLayer.pixels.taboola.event_names.start_checkout,
			};
		}
		
		/**
		 * Adapt view_content event
		 * No product value transmitted, as Taboola only supports the "revenue" field.
		 */
		adaptViewContent(eventData) {
			const data = {
				id: wpmDataLayer.pixels.taboola.account_id,
				notify: 'event',
				name: wpmDataLayer.pixels.taboola.event_names.view_content,
			};
			
			if (eventData?.product) {
				const product = eventData.product;
				data.currency = product.currency;
				data.quantity = product.quantity;
				data.revenue = product.quantity * product.price;
			}
			
			return data;
		}
		
		/**
		 * Adapt purchase event
		 */
		adaptPurchase(eventData) {
			const data = {
				id: wpmDataLayer.pixels.taboola.account_id,
				notify: 'event',
				name: wpmDataLayer.pixels.taboola.event_names.purchase,
				revenue: wpmDataLayer.order.value.marketing,
				currency: wpmDataLayer.order.currency,
				orderid: wpmDataLayer.order.id,
			};
			
			// Get order item count
			if (wpmDataLayer.order.items) {
				let itemCount = 0;
				wpmDataLayer.order.items.forEach(item => {
					itemCount += parseInt(item.quantity);
				});
				
				data.quantity = itemCount;
			}
			
			return data;
		}
	}
	
	// Register the adapter
	wpm.registerAdapter('taboola', new TaboolaAdapter(), {
		supportsS2S: false,
		supportsEventDeduplication: false,
		isActive: () => wpmDataLayer?.pixels?.taboola?.account_id ? true : false
	});
	
}(window.wpm = window.wpm || {}, jQuery));
