// Pixel load event listener
jQuery(document).on("pmw:load-pixels", () => {

	if (wpmDataLayer?.pixels?.taboola?.account_id && !wpmDataLayer?.pixels?.taboola?.loaded) {
		if (wpm.consent.canPixelBeFired("marketing", "Taboola")) wpm.loadTaboolaPixel()
	}
})

// view search event
jQuery(document).on("pmw:browser:search", (event, payload) => {

	try {
		if (wpm.canNotFireTaboolaEvent()) return

		const taboolaData = payload.pixels?.taboola;
		if (!taboolaData) return;

		_tfa.push(taboolaData)
		pmw.console.log("Taboola: search event sent", taboolaData)

	} catch (e) {
		console.error(e)
	}
})

